&lt;div class=&quot;s6&quot; style=&quot;line-height: 1.2; padding-left: 40px;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;s8&quot;&gt;•&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;s4&quot;&gt;Proven success developing strategic logistics partnerships and optimizing first-mile, fulfillment center, and last-mile operations.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div class=&quot;s6&quot; style=&quot;line-height: 1.2; padding-left: 40px;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;s8&quot;&gt;•&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;s4&quot;&gt;Strong track record of driving significant cost reduction and operational efficiency improvements within complex, high-volume distribution networks.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
