&lt;p class=&quot;s3&quot; style=&quot;line-height: 1.2;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span class=&quot;s4&quot;&gt;ADDITIONAL REQUIREMENTS:&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
